<?php
class views{
  const version='1.2.0';
  protected $dir;
  protected $file;
  protected $user;
  protected $font;
  protected $color;
  protected $monitor;
  function __construct(){
    $this->user=$_GET['user']??false;
    $this->dir=defined('VIEWS_CLI_DIR')
      ?VIEWS_CLI_DIR:__DIR__.'/views.storage';
    $this->dir.=substr($this->dir,-1)!='/'?'/':'';
    $this->file=$this->dir.$this->user;
    $this->font=$this->font();
    $this->color=$this->colors($_GET['color']??'');
    $this->monitor=isset($_GET['monitor']);
    if(!is_dir($this->dir)){
      @mkdir($this->dir,0755,true);
    }
    $ptrn='/^[a-z\d](?:[a-z\d]|-(?=[a-z\d])){0,38}$/i';
    if($this->user&&preg_match($ptrn,$this->user)){
      if(is_file($this->file)){
        return $this->start();
      }elseif(isset($_GET['register'])
        &&$this->register($_GET['register'])){
        $put=file_put_contents($this->file,str_repeat('0',0x20));
        return $this->start();
      }
    }elseif(isset($_GET['build'])){
      return $this->build($_GET['build']);
    }elseif(isset($_GET['rusers'])){
      return $this->users();
    }return $this->error();
  }
  protected function start(){
    if($this->monitor){
      return $this->out($this->file);
    }
    $count=$this->get($this->file)+1;
    $file=$this->create($count);
    $this->set($this->file,$count);
    return $this->out($file);
  }
  protected function font(){
    $dir=defined('VIEWS_FONT_DIR')
      ?VIEWS_FONT_DIR:__DIR__.'/';
    $file=$dir.'views.ttf';
    if(!is_file($file)){
      $raw=base64_decode($this->ttf());
      $put=file_put_contents($file,$raw);
    }return $file;
  }
  protected function users(){
    $scan=@scandir($this->dir);
    $scan=is_array($scan)?$scan:[];
    $users=array_diff($scan,['.','..']);
    $json=@json_encode(array_values($users),JSON_PRETTY_PRINT);
    $json=$json?$json:'[]';
    header('Content-Type: text/plain');
    header('Content-Length: '.strlen($json));
    header('HTTP/1.1 200 OK');
    exit($json);
  }
  protected function create(int $count){
    $text=$this->user.': '.(string)$count.' views';
    $r=$this->file;
    $font=$this->font;
    $d=imagecreatefromstring($this->sample());
    $red=$this->color->red;
    $yellow=$this->color->yellow;
    $blue=$this->color->blue;
    $w=4+ceil(strlen($text)*12.8);
    $h=24;
    $size=16;
    $angle=0;
    $x=2;
    $y=18;
    $dpi=96;
    $quality=80;
    $n=imagecreatetruecolor($w,$h);
    imagecopyresampled($n,$d,0,0,0,0,$w,$h,1,1);
    $color=imagecolorallocate($n,$red,$yellow,$blue);
    $write=imagettftext($n,$size,$angle,$x,$y,$color,$font,$text);
    imageresolution($n,$dpi);
    imagepng($n,$r,min(floor($quality*0.1),9));
    return $r;
  }
  protected function error(){
    header('Content-Type: image/jpeg');
    header('Content-Length: '.strlen($this->sample()));
    header('HTTP/1.1 200 OK');
    exit($this->sample());
  }
  protected function build(string $reg){
    $build=$this->sign($reg);
    if($build){
      header('Content-Description: File Transfer');
      header('Content-Disposition: attachment; '
        .'filename="views.bin"');
      header('Content-Type: application/octet-stream');
    }else{
      header('Content-Type: text/plain');
      $build='false';
    }
    header('Content-Length: '.strlen($build));
    header('HTTP/1.1 200 OK');
    exit($build);
  }
  protected function sign(string $reg){
    $ptrn='#^([^/]+)/([^/]+)/([^/]+)$#';
    if(!preg_match($ptrn,$reg,$akur)){
      return false;
    }
    $raw=gzdeflate(md5($reg,true));
    $def=gzdeflate(implode($raw,$akur));
    return $def;
  }
  protected function register(string $reg){
    $ptrn='#^github\.com/([^/]+)/([^/]+)/tree/([^/]+)$#';
    if(!preg_match($ptrn,$reg,$akur)){
      return false;
    }
    $name='views.bin';
    $host='https://raw.githubusercontent.com';
    $path="{$akur[1]}/{$akur[2]}/{$akur[3]}";
    $file="{$host}/{$path}/{$name}";
    $get=@file_get_contents($file);
    if($get==$this->sign($path)){
      return true;
    }return false;
  }
  protected function colors(string $color){
    $def=(object)[
      'red'=>0,
      'yellow'=>0,
      'blue'=>0,
    ];
    $ptrn='/^(\d{1,3}),(\d{1,3}),(\d{1,3})$/';
    if(!preg_match($ptrn,$color,$akur)){
      return $def;
    }
    return (object)[
      'red'=>min($akur[1],0xff),
      'yellow'=>min($akur[2],0xff),
      'blue'=>min($akur[3],0xff),
    ];
  }
  protected function out(string $file){
    if(headers_sent()){exit;}
    $info=getimagesize($file);
    $mime=isset($info['mime'])?$info['mime']:'image/jpeg';
    $bname=basename($file);
    $fname=$bname.'.'.md5_file($file).'.'
        .preg_replace('/^[^\/]+\//i','',$mime);
    header('Expires: 0');
    header('Cache-Control: must-revalidate');
    header('Pragma: public');
    header('Cache-Control: public, max-age=1');
    header('Content-Description: File Transfer');
    header('Content-Disposition: attachment; filename="'.$fname.'"');
    header('Content-Type: '.$mime);
    header('Content-Length: '.filesize($file));
    header('HTTP/1.1 200 OK');
    @readfile($file);
    exit;
  }
  protected function set(string $file,int $count):bool{
    if(!is_file($file)){
      return false;
    }
    $s=filesize($file);
    $o=fopen($file,'ab');
    if(!is_resource($o)||$s<0xf){
      return false;
    }
    $d=base_convert((string)$count,0xa,0x24);
    $n=sprintf('%015s',$d);
    $w=fwrite($o,$n);
    fclose($o);
    return $w?true:false;
  }
  protected function get(string $file):int{
    if(!is_file($file)){
      return 0;
    }
    $s=filesize($file);
    $o=fopen($file,'rb');
    if(!is_resource($o)||$s<0xf){
      return 0;
    }
    fseek($o,$s-0xf);
    $r=fread($o,0xf);
    fclose($o);
    $n=base_convert(trim($r),0x24,0xa);
    return preg_match('/^\d+$/',$n)?intval($n):0;
  }
  protected function sample(){
    $head='data:image/jpeg;base64,';
    $base='';
    return base64_decode($base);
  }
  protected function ttf(){
    $head='data:font/ttf;base64,';
    return '';
  }
}


